	function initLoadMore() {
		const commentsList = document.getElementById("comments-list");
		// Find load more button by checking for "Load more" text content
		const loadMoreBtn = findLoadMoreButton();

		if (!commentsList || !loadMoreBtn) {
			console.warn("Load more comments: Required elements not found");
			return;
		}

		// Track already loaded comments by comment-id attribute
		const existingComments = commentsList.querySelectorAll(".comment-container");

		existingComments.forEach((comment) => {
			const commentId = comment.getAttribute("comment-id");
			if (commentId) loadedCommentIds.add(commentId);
		});
		commentsOffset = existingComments.length;

		// Hide button if fewer than limit comments loaded initially
		if (existingComments.length < COMMENTS_LIMIT) {
                        console.log('initLoadMore setting load more to none',existingComments.length,COMMENTS_LIMIT)
			loadMoreBtn.style.display = "none";
		}

		// Bind click event
		loadMoreBtn.addEventListener("click", handleLoadMore);
	}

	function findLoadMoreButton() {
		// Find button containing "Load more" text
		const buttons = document.querySelectorAll("button");
		for (const btn of buttons) {
			if (btn.textContent.toLowerCase().includes("load more")) {
				return btn;
			}
		}
		// Fallback: find by ID (if it has one)
		return document.getElementById("load-more-btn");
	}

	async function handleLoadMore(e) {
		e.preventDefault();

		if (isLoading || !hasMoreComments) return;

		const loadMoreBtn = e.currentTarget;
		const originalText = loadMoreBtn.innerHTML;

		isLoading = true;
		loadMoreBtn.disabled = true;
		setButtonText(loadMoreBtn, "Loading...");

		try {
			const postId = getPostId();
			if (!postId) {
				throw new Error("Post ID not found");
			}

			const comments = await fetchComments(postId, commentsOffset, COMMENTS_LIMIT);

			if (comments.length === 0) {
              console.log('handleLoadMore setting load more to none')
				hasMoreComments = false;
				loadMoreBtn.style.display = "none";
				return;
			}

			const commentsList = document.getElementById("comments-list");
			// Find the container that holds all comment sections (first child div of comments-list)
			const commentsContainer = commentsList.querySelector("div") || commentsList;

			comments.forEach((comment) => {
				if (!loadedCommentIds.has(comment.name)) {
					const result = renderComment(comment);
					if (typeof result === "string") {
						commentsContainer.insertAdjacentHTML("beforeend", result);
					} else {
						commentsContainer.appendChild(result);
					}
					loadedCommentIds.add(comment.name);
				}
			});

			commentsOffset += comments.length;

			// Hide button if fewer than limit returned
			if (comments.length < COMMENTS_LIMIT) {
              console.log('comments.length < COMMENTS_LIMIT setting load more to none')

				hasMoreComments = false;
				loadMoreBtn.style.display = "none";
			}
		} catch (error) {
			console.error("Failed to load more comments:", error);
			setButtonText(loadMoreBtn, "Error - Try Again");
			loadMoreBtn.disabled = false;
			isLoading = false;
			return;
		}

		loadMoreBtn.innerHTML = originalText;
		loadMoreBtn.disabled = false;
		isLoading = false;
	}

	function setButtonText(btn, text) {
		// Try to find text element inside button, fallback to button textContent
		const textEl = btn.querySelector('[class*="__text_block__"]') || btn;
		if (textEl.tagName === "BUTTON") {
			btn.textContent = text;
		} else {
			textEl.textContent = text;
		}
	}

	function getPostId() {
		// Try multiple sources for post ID
		if (typeof page_data !== "undefined" && page_data.post && page_data.post.name) {
			return page_data.post.name;
		}

		// Look for element with post-id attribute (comment input section)
		const postIdEl = document.querySelector("[post-id]");
		if (postIdEl) {
			return postIdEl.getAttribute("post-id");
		}

		// Try to extract from URL path
		const pathMatch = window.location.pathname.match(/\/cafe\/post\/([^\/]+)/);
		if (pathMatch) return pathMatch[1];

		return null;
	}

