	function formatRelativeTime(dateString) {
		const date = new Date(dateString);
		const now = new Date();
		const diffMs = now - date;
		const diffSecs = Math.floor(diffMs / 1000);
		const diffMins = Math.floor(diffSecs / 60);
		const diffHours = Math.floor(diffMins / 60);
		const diffDays = Math.floor(diffHours / 24);

		if (diffSecs < 60) return "Just now";
		if (diffMins < 60) return `${diffMins} minute${diffMins !== 1 ? "s" : ""} ago`;
		if (diffHours < 24) return `${diffHours} hour${diffHours !== 1 ? "s" : ""} ago`;
		if (diffDays < 30) return `${diffDays} day${diffDays !== 1 ? "s" : ""} ago`;
		if (diffDays < 365)
			return `${Math.floor(diffDays / 30)} month${Math.floor(diffDays / 30) !== 1 ? "s" : ""} ago`;
		return `${Math.floor(diffDays / 365)} year${Math.floor(diffDays / 365) !== 1 ? "s" : ""} ago`;
	}

	function generateBlockUid() {
		return Math.random().toString(36).substring(2, 8) + "-" + Math.floor(Math.random() * 10);
	}

	function escapeHtml(text) {
		const div = document.createElement("div");
		div.textContent = text;
		return div.innerHTML;
	}
})();

async function submitComment(postName) {
	const commentInput = document.getElementById("comment-input");
	const content = commentInput?.value?.trim();

	if (!content) {
		return;
	}

	const url = "/api/resource/Cafe Post Comment";

	const payload = {
		doctype: "Cafe Post Comment",
		content: content,
		post: postName,
	};

	try {
		const response = await fetch(url, {
			method: "POST",
			headers: {
				"Content-Type": "application/json",
				"X-Frappe-CSRF-Token": frappe.csrf_token || "",
			},
			body: JSON.stringify(payload),
		});

		if (!response.ok) {
			const error = await response.json();
			throw new Error(error.message || "Failed to submit comment");
		}

		const result = await response.json();

		// Clear the input after successful submission
		commentInput.value = "";
        window.location.reload()
		// Add the new comment to the list
		// addCommentToList(result.data);

		return result;
	} catch (error) {
		console.error("Error submitting comment:", error);
		throw error;
	}
}

function addCommentToList(commentData) {
	const commentsList = document.getElementById("comments-list");
	if (!commentsList) return;

	// Get current user info from frappe
	const userName = frappe.session_user || frappe.user?.name || "Anonymous";
	const userImage = frappe.user?.image || "/files/stock-image.jpg";

	// Clone an existing comment to preserve dynamic builder classes
	const existingComment = commentsList.querySelector("section");
	if (!existingComment) return;

	const newComment = existingComment.cloneNode(true);

	// Update user info
	const userNameEl = newComment.querySelector(".comment-user-name");
	if (userNameEl) userNameEl.textContent = userName;

	const userImgEl = newComment.querySelector(".comment-user-image");
	if (userImgEl) userImgEl.src = userImage;

	// Update content
	const contentEl = newComment.querySelector(".comment-content");
	if (contentEl) contentEl.textContent = commentData.content;

	// Update creation time
	const dateEl = newComment.querySelector(".comment-creation-date");
	if (dateEl) dateEl.textContent = "just now";

	// Reset like count
	const likeCountEl = newComment.querySelector(".comment-like-count");
	if (likeCountEl) likeCountEl.textContent = "0";

	// Reset like icon to unfilled state
	const likeIconPath = newComment.querySelector(".comment-like-icon path");
	if (likeIconPath) likeIconPath.setAttribute("fill", "#525252");

	// Prepend the new comment to the list
	commentsList.insertBefore(newComment, commentsList.firstChild);
}

document.getElementById("comment-submit-btn")?.addEventListener("click",  () =>{
	const postId = this.getAttribute("post-id");
	submitComment(postId);
});

document.getElementById("comment-input")?.addEventListener("keydown",  (event) =>{
  if (event.key === "Enter") {
    event.preventDefault()
    const postId = this.getAttribute("post-id");
	submitComment(postId);
  }
})
